#include <bits/stdc++.h>
using namespace std;

long long connectRopes(vector<int>& arr) {
    priority_queue<int, vector<int>, greater<int>> pq;
    for (int v : arr) pq.push(v);
    long long cost = 0;
    while (pq.size() > 1) {
        int a = pq.top(); pq.pop();
        int b = pq.top(); pq.pop();
        cost += a + b;
        pq.push(a + b);
    }
    return cost;
}

