import java.util.PriorityQueue;

class Solution {
    public long connectRopes(int[] arr) {
        PriorityQueue<Integer> pq = new PriorityQueue<>();
        for (int v : arr) pq.offer(v);
        long cost = 0;
        while (pq.size() > 1) {
            int a = pq.poll(), b = pq.poll();
            cost += a + b;
            pq.offer(a + b);
        }
        return cost;
    }
}
